let cartCount = 0;

function formatPrice(price) {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: 'USD'
  }).format(price);
}

function createProductCard(product) {
  const card = document.createElement('article');
  card.className = 'product-card';
  card.setAttribute('aria-labelledby', `title-${product.id}`);

  let badges = '';
  if (product.isNew) {
    badges += `<span class="badge badge-new">New</span>`;
  }
  if (product.isSale) {
    badges += `<span class="badge badge-sale">Sale</span>`;
  }

  let priceHTML = `<span class="price">${formatPrice(product.price)}</span>`;
  if (product.originalPrice) {
    priceHTML = `
      <span class="price price-sale">${formatPrice(product.price)}</span>
      <span class="price-original">
        <span class="sr-only">Original price: </span>${formatPrice(product.originalPrice)}
      </span>
    `;
  }

  card.innerHTML = `
    <div class="product-image-wrapper">
      ${badges}
      <img src="${product.image}" alt="${product.alt}" class="product-image" loading="lazy">
    </div>
    <div class="product-info">
      <h3 id="title-${product.id}" class="product-title">
        <a href="/product/${product.id}">${product.title}</a>
      </h3>
      <div class="product-price-wrapper">
        ${priceHTML}
      </div>
      <button class="btn btn-primary btn-add-cart" data-id="${product.id}" aria-label="Add ${product.title} to cart">
        Add to Cart
      </button>
    </div>
  `;

  return card;
}

function renderProducts(productsArray, containerId) {
  const container = document.getElementById(containerId);
  if (!container) return;

  container.innerHTML = '';
  productsArray.forEach(product => {
    container.appendChild(createProductCard(product));
  });
}

function updateCartCount(newCount) {
  cartCount = newCount;
  const countEls = document.querySelectorAll('.cart-count');
  const btnEl = document.querySelector('.cart-btn');

  countEls.forEach(el => {
    el.textContent = cartCount;
  });

  if (btnEl) {
    btnEl.setAttribute('aria-label', `Cart, ${cartCount} items`);
  }
}

document.addEventListener('DOMContentLoaded', () => {
