/* CSS Custom Properties for Theming */
:root {
  --color-primary: #111827;
  --color-secondary: #4b5563;
  --color-accent: #3b82f6;
  --color-accent-hover: #2563eb;
  --color-background: #ffffff;
  --color-surface: #f3f4f6;
  --color-text: #111827;
  --color-text-muted: #6b7280;
  --color-border: #e5e7eb;
  --color-error: #ef4444;
  --color-success: #10b981;
  --color-sale: #dc2626;

  --font-sans: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
  --font-serif: Georgia, Cambria, "Times New Roman", Times, serif;

  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-6: 1.5rem;
  --space-8: 2rem;
  --space-12: 3rem;
  --space-16: 4rem;

  --radius-sm: 0.125rem;
  --radius-md: 0.375rem;
  --radius-lg: 0.5rem;

  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
}

/* Base Styles & Reset */
*, *::before, *::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  font-family: var(--font-sans);
  color: var(--color-text);
  background-color: var(--color-background);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

h1, h2, h3, h4, p {
  margin-top: 0;
}

a {
  color: var(--color-primary);
  text-decoration: none;
  transition: color 0.2s;
}

a:hover, a:focus {
  color: var(--color-accent);
  text-decoration: underline;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

/* Accessibility Utilities */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border-width: 0;
}

.skip-link {
  position: absolute;
  top: -40px;
  left: 0;
  background: var(--color-primary);
  color: white;
  padding: var(--space-2) var(--space-4);
  z-index: 100;
  transition: top 0.2s;
}

.skip-link:focus {
  top: 0;
  text-decoration: none;
}

:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}

/* Layout */
.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 var(--space-4);
}

/* Header */
.site-header {
  border-bottom: 1px solid var(--color-border);
  padding: var(--space-4) 0;
  position: sticky;
  top: 0;
  background: var(--color-background);
  z-index: 50;
}

.header-container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: var(--space-4);
}

.logo a {
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: -0.025em;
  text-decoration: none;
}

.main-nav ul {
  display: flex;
  list-style: none;
  padding: 0;
  margin: 0;
  gap: var(--space-6);
}

.main-nav a {
  font-weight: 500;
  color: var(--color-secondary);
  text-decoration: none;
}

.main-nav a:hover, .main-nav a:focus {
  color: var(--color-primary);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: var(--space-4);
}

.search-form {
  display: flex;
  position: relative;
}

.search-form input {
  padding: var(--space-2) var(--space-8) var(--space-2) var(--space-3);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  font-size: 0.875rem;
  width: 200px;
}

.search-form button {
  position: absolute;
  right: var(--space-2);
  top: 50%;
  transform: translateY(-50%);
  color: var(--color-text-muted);
  display: flex;
  align-items: center;
  justify-content: center;
}

.cart-btn {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  color: var(--color-primary);
  position: relative;
  padding: var(--space-2);
}

.cart-count {
  background: var(--color-accent);
  color: white;
  font-size: 0.75rem;
  font-weight: bold;
  height: 20px;
  min-width: 20px;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  position: absolute;
  top: -2px;
  right: -5px;
  padding: 0 4px;
}

/* Hero Section */
.hero {
  background-color: var(--color-surface);
  padding: var(--space-16) 0;
  text-align: center;
}

.hero-content {
  max-width: 600px;
  margin: 0 auto;
}

.hero h1 {
  font-size: 2.5rem;
  font-weight: 800;
  margin-bottom: var(--space-4);
  line-height: 1.2;
}

.hero p {
  font-size: 1.125rem;
  color: var(--color-secondary);
  margin-bottom: var(--space-8);
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: var(--space-3) var(--space-6);
  border-radius: var(--radius-md);
  font-weight: 600;
  text-decoration: none;
  transition: all 0.2s;
  cursor: pointer;
}

.btn-primary {
  background-color: var(--color-primary);
  color: white;
  border: 1px solid var(--color-primary);
}

.btn-primary:hover, .btn-primary:focus {
  background-color: var(--color-secondary);
  border-color: var(--color-secondary);
  text-decoration: none;
  color: white;
}

.btn-secondary {
  background-color: white;
  color: var(--color-primary);
  border: 1px solid var(--color-border);
}

.btn-secondary:hover, .btn-secondary:focus {
  background-color: var(--color-surface);
  text-decoration: none;
}

.btn-add-cart {
  width: 100%;
  margin-top: var(--space-4);
}

/* Product Sections */
.product-section {
  padding: var(--space-12) 0;
}

.deals-section {
  background-color: var(--color-surface);
}

.product-section h2 {
  font-size: 2rem;
  margin-bottom: var(--space-8);
  text-align: center;
}

.product-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
  gap: var(--space-8);
}

/* Product Card */
.product-card {
  background: var(--color-background);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: box-shadow 0.2s;
  display: flex;
  flex-direction: column;
}

.product-card:hover {
  box-shadow: var(--shadow-md);
}

.product-image-wrapper {
  position: relative;
  aspect-ratio: 1 / 1;
  overflow: hidden;
  background-color: var(--color-surface);
}

.product-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.3s ease;
}

.product-card:hover .product-image {
  transform: scale(1.05);
}

.badge {
  position: absolute;
  top: var(--space-2);
  left: var(--space-2);
  padding: var(--space-1) var(--space-2);
  font-size: 0.75rem;
  font-weight: bold;
  border-radius: var(--radius-sm);
  z-index: 10;
}

.badge-sale {
  background-color: var(--color-sale);
  color: white;
}

.badge-new {
  background-color: var(--color-accent);
  color: white;
}

.product-info {
  padding: var(--space-4);
  display: flex;
  flex-direction: column;
  flex-grow: 1;
}

.product-title {
  font-size: 1.125rem;
  margin-bottom: var(--space-2);
}

.product-title a {
  color: inherit;
  text-decoration: none;
}

.product-title a::after {
  content: '';
  position: absolute;
  inset: 0;
}

.product-price-wrapper {
  display: flex;
  align-items: baseline;
  gap: var(--space-2);
  margin-bottom: auto;
}

.price {
  font-weight: 600;
  font-size: 1.125rem;
}

.price-original {
  text-decoration: line-through;
  color: var(--color-text-muted);
  font-size: 0.875rem;
}

.price-sale {
  color: var(--color-sale);
}

/* Editorial Section */
.editorial-section {
  padding: var(--space-12) 0;
}

.editorial-section h2 {
  font-size: 2rem;
  margin-bottom: var(--space-8);
  text-align: center;
}

.editorial-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: var(--space-8);
}

.editorial-card {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
  aspect-ratio: 16 / 9;
}

.editorial-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.editorial-content {
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(0,0,0,0.8), rgba(0,0,0,0.2));
  color: white;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  padding: var(--space-6);
}

.editorial-content h3 {
  font-size: 1.5rem;
  margin-bottom: var(--space-2);
}

.editorial-content a {
  color: white;
}

.editorial-content p {
  margin-bottom: 0;
  color: rgba(255, 255, 255, 0.9);
}

/* Footer */
.site-footer {
  background-color: var(--color-primary);
  color: white;
  padding: var(--space-12) 0 var(--space-4);
}

.footer-container {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: var(--space-8);
  margin-bottom: var(--space-12);
}

.footer-title {
  font-size: 1.125rem;
  margin-bottom: var(--space-4);
  color: white;
}

.site-footer p {
  color: var(--color-text-muted);
}

.site-footer ul {
  list-style: none;
  padding: 0;
  margin: 0;
}

.site-footer li {
  margin-bottom: var(--space-2);
}

.site-footer a {
  color: var(--color-text-muted);
}

.site-footer a:hover, .site-footer a:focus {
  color: white;
}

.input-group {
  display: flex;
  margin-bottom: var(--space-2);
}

.input-group input {
  flex-grow: 1;
  padding: var(--space-2) var(--space-3);
  border: 1px solid var(--color-secondary);
  background: var(--color-secondary);
  color: white;
  border-radius: var(--radius-md) 0 0 var(--radius-md);
}

.input-group input::placeholder {
  color: #9ca3af;
}

.input-group button {
  border-radius: 0 var(--radius-md) var(--radius-md) 0;
  border: 1px solid var(--color-accent);
  background: var(--color-accent);
  color: white;
}

.input-group button:hover, .input-group button:focus {
  background: var(--color-accent-hover);
}

.footer-bottom {
  text-align: center;
  border-top: 1px solid var(--color-secondary);
  padding-top: var(--space-4);
}

.footer-bottom p {
  font-size: 0.875rem;
  margin: 0;
}

.status-message {
  font-size: 0.875rem;
  min-height: 1.25rem;
}
.status-success {
  color: #34d399;
}
.status-error {
  color: #f87171;
}

/* Responsive */
@media (max-width: 768px) {
  .header-container {
    flex-direction: column;
    align-items: stretch;
  }

  .logo {
    text-align: center;
  }

  .main-nav ul {
    justify-content: center;
    flex-wrap: wrap;
  }

  .header-actions {
    justify-content: space-between;
  }

  .search-form {
    flex-grow: 1;
  }

  .search-form input {
    width: 100%;
  }

  .editorial-card {
    aspect-ratio: 1 / 1;
  }
}

/* Forced Colors */
@media (forced-colors: active) {
  .btn, .badge, .cart-count {
    border: 1px solid ButtonBorder;
  }

  .skip-link {
    background: Canvas;
    color: LinkText;
    border: 1px solid LinkText;
  }

  .editorial-content {
    background: Canvas;
    color: CanvasText;
  }

  .editorial-content a {
    color: LinkText;
  }

  .site-footer, .hero, .deals-section {
    background: Canvas;
    border-top: 1px solid CanvasText;
  }

  .input-group input, .search-form input {
    border: 1px solid ButtonBorder;
  }
}

