  margin-bottom: var(--space-12);
}

.footer-title {
  font-size: 1.125rem;
  margin-bottom: var(--space-4);
  color: white;
}

.site-footer p {
  color: var(--color-text-muted);
}

.site-footer ul {
  list-style: none;
  padding: 0;
  margin: 0;
}

.site-footer li {
