  padding: var(--space-2) var(--space-4);
  z-index: 100;
  transition: top 0.2s;
}

.skip-link:focus {
  top: 0;
  text-decoration: none;
}

:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}

/* Layout */
.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 var(--space-4);
}

/* Header */
.site-header {
  border-bottom: 1px solid var(--color-border);
  padding: var(--space-4) 0;
  position: sticky;
  top: 0;
  background: var(--color-background);
  z-index: 50;
}

.header-container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: var(--space-4);
}

.logo a {
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: -0.025em;
  text-decoration: none;
}

.main-nav ul {
  display: flex;
  list-style: none;
  padding: 0;
  margin: 0;
  gap: var(--space-6);
}

.main-nav a {
  font-weight: 500;
  color: var(--color-secondary);
  text-decoration: none;
}

.main-nav a:hover, .main-nav a:focus {
  color: var(--color-primary);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: var(--space-4);
}

.search-form {
  display: flex;
  position: relative;
}

.search-form input {
  padding: var(--space-2) var(--space-8) var(--space-2) var(--space-3);
