  border: 1px solid var(--color-border);
}

.btn-secondary:hover, .btn-secondary:focus {
  background-color: var(--color-surface);
  text-decoration: none;
}

.btn-add-cart {
  width: 100%;
  margin-top: var(--space-4);
}

